#!/usr/bin/env bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# hdd_run.sh (kit v6): one monerod sync run on a rotating disk, with I/O sampling and, optionally, a memory cap.
# For the HDD VM.
#
# What it does, in order:
#   1. copies the snapshot's data.mdb into $DATA_DIR/testnet/lmdb/ (on the HDD), checks the copy's size, then flushes
#      and drops the guest page cache (needs sudo for /proc/sys/vm/drop_caches);
#   1a. (v4, if MEM_MAX is set) creates a transient systemd scope with that MemoryMax; the walk (1b) and monerod (3)
#      run inside it, so the page cache they fault in and monerod's own memory count against the cap;
#   1b. (if WARM_DBS is set) reads the named LMDB sub-DBs with mdb_dump, with the data disk's read-ahead at 0, or (v5,
#      with WARM_TOOL) with that tool, read-ahead as it is;
#   2. starts iostat, vmstat and pidstat samplers, once a second;
#   3. starts monerod, peering with $PEER only (exclusive node, one outgoing connection, no incoming,
#      P2P bound to 127.0.0.1), RPC on 127.0.0.1 only;
#   4. polls the height every 2 s, the process's /proc/<pid>/io, CPU and memory every 1 s, and the scope's memory
#      every 2 s, until the top block is $TARGET_TOP, the timeout, or monerod exits;
#   5. records the top block's hash, stops monerod over RPC, stops the samplers, reads the scope's counters, stops the
#      scope, writes summary.txt.
# It touches nothing outside $OUT and $DATA_DIR (and, with MEM_MAX, one transient scope unit, stopped at the end).
# No network access except RPC on 127.0.0.1 and P2P to $PEER.
# It aborts (exit 2 or 3, before monerod starts) if: $DATA_DIR's lmdb directory is the snapshot's own directory; the
# disk lacks room; something already listens on $RPC_PORT; any restore step fails; the restored file's size differs
# from the snapshot's; the page cache cannot be dropped; or the scope cannot be set up. It also stops (exit 4) if
# monerod does not answer RPC. An OOM-kill inside the scope, and a timeout, are results (exit 0), not aborts.
#
# v2 (2026-11-09) against v1: the abort checks above (the lab coordinator's report: a failed dd went unnoticed); RESULT gains
# blocks, warmup_s (RPC answering to the first block added), steady_blocks_per_s (after that), and iostat means
# for the data disk over the sync window.
#
# v3 (2026-11-09) against v2:
#   - optional WARM_DBS: after the cache drop and before the samplers/monerod start, each named LMDB sub-DB is read
#     with `mdb_dump -s <db> > /dev/null` (timed; sectors read from /sys/block/<disk>/stat). No cache drop after it.
#     Read-ahead is set to 0 for the walk (mdb_dump has no MDB_NORDAHEAD: 5.8 GB vs 0.83 GB cached on my test box's real DB)
#     and restored afterwards (also on abort); needs sudo for the sysfs write; RA_FILE overrides the sysfs file.
#   - page-cache residency of the restored data.mdb (fincore): resident_MB_start/end in RESULT and a residency.csv
#     sampled every RES_EVERY_S s; rpc_epoch in the summary aligns the samples with height.csv.
#   - WINDOW lines: blocks/s and read/write kB per block for each WINDOW_BLOCKS-block window (from height.csv, proc.csv).
#   - RESULT gains warm_s, warm_read_MB, resident_MB_start, resident_MB_end (before hash_at_...).
#
# v4 (2026-11-09) against v3 (everything in v3 is unchanged when MEM_MAX is empty, except the RESULT fields added):
#   - optional MEM_MAX (a systemd MemoryMax value: infinity, 2048M, 1536M, ...). After the cache drop the kit runs
#       sudo systemd-run --scope --unit=hddrun-<time>-<pid> -p MemoryMax=$MEM_MAX -p MemorySwapMax=0 \
#         -p OOMPolicy=continue -- sleep infinity
#     and checks the scope's memory.max. The walk's mdb_dump processes and monerod each join the scope before they
#     exec (their PID is written to the scope's cgroup.procs with sudo, then checked), so the walk's page cache and
#     everything monerod uses count against the cap. The restore, the cache drop, the samplers and the kit stay
#     outside it. The `sleep infinity` holds the scope open, and OOMPolicy=continue keeps systemd from stopping the
#     scope after an OOM-kill (its default, stop, may), so its counters can still be read. The kit stops the scope at the end and on abort.
#     MEM_MAX=infinity gives a scope with no cap (the same counters, no limit).
#   - an OOM-kill inside the scope is a result: RESULT outcome=oom_killed (or oom_killed_walk, oom_killed_startup), exit 0.
#     After an OOM-kill, or any other exit of monerod during the sync (outcome=exited), the kit restarts monerod
#     offline, outside the scope, reads the DB's top block and its hash, and stops it (post_check; POST_CHECK=0 skips it).
#   - a timeout is a result too: outcome=timeout, with the hash read at the top reached.
#   - RESULT gains, before hash_at_: outcome, mem_max, cg_peak_MB (memory.peak), cg_anon_max_MB and cg_file_max_MB (max
#     of the 2 s samples of memory.stat anon and file), cg_oom, cg_oom_kill, cg_high, cg_max (memory.events),
#     cg_refault_file (memory.stat workingset_refault_file at the end), rss_anon_max_MB (monerod's RssAnon), post_check.
#     hash_at_<H> is at TARGET_TOP when it was reached, else at the top reached. All cg_ fields are na without a scope.
#   - cgmem.csv: the scope's memory.current and memory.stat fields every 2 s; proc.csv gains rss_anon_kb, rss_file_kb.
#   - a failed RPC poll no longer sets the top to -1; proc.csv rows are written only while /proc/<pid>/io is readable.
#   - the summary logs MemAvailable, swap, systemd-oomd's state and the MGLRU setting.
#
# v4.1 (2026-11-09) against v4: the wait for the scope (1a) and its cleanup only (found by the lab coordinator in stage 3, run 2):
#   - v4 tested the backgrounded `sudo systemd-run` with `kill -0`. sudo runs with real UID 0 during its policy check
#     (setresuid(0,-1,-1) first, the user's real UID again only before it runs the command). A `kill -0` from the user
#     in that window fails with EPERM, so the loop took the holder for dead and aborted. The window lasts about 27 ms
#     on an SSD box right after a cache drop, and longer on the VM's HDD, where the kit runs it right after one.
#   - v4.1 asks bash's job table instead (`jobs -rp`): no signal, no /proc. The wait is 30 s (was 15 s), and the abort
#     says whether the holder had exited or the scope was simply not visible in time. On that abort, the cleanup ends a
#     holder that is still running (sudo kill) before it stops the unit, so a late scope cannot be left behind.
#
# v5 (2026-11-10, G015 stage 4b) against v4.1. With WARM_TOOL unset, a run is as in v4.1, except for the RESULT
# fields added:
#   - optional WARM_TOOL. With WARM_DBS, the warm step runs `$WARM_TOOL <lmdb dir> all $WARM_DBS` once, instead of
#     mdb_dump, inside the scope if there is one. The tool is warmcheck, linked with monerodato .5's LMDB: it calls
#     mdb_env_warm_dbis, the function monerod .5 runs at startup. The read-ahead is left as it is, as it is for
#     monerod. The tool's own RESULT line goes into the summary, as "warm tool: ...".
#   - times from monerod's launch: RESULT gains launch_to_rpc_s and launch_to_top_s (to the target top; na if it was
#     not reached). wall_s still counts from the first RPC answer. For monerodato .5 that is after its startup
#     warm-up, so only launch_to_top_s compares the arms.
#   - read_MB_launch: monerod's read_bytes at the last sample, which is everything it read since launch, its warm-up
#     included. disk_read_MB still counts from the first sample after RPC answered.
#   - monerod_warmup_s and monerod_warmup_MB, from monerod .5's "Index warm-up" log line (na without one).
#
# v6 (2026-11-11, G015 stage 4c) against v5: the warm-up fields only. monerodato .6-prep reads the indexes in a
# background thread and logs two "Index warm-up" lines: one at the start, one at the end. v5 took the first line,
# which for .6-prep is the start line, so monerod_warmup_s and monerod_warmup_MB came out na.
#   - monerod_warmup_s and monerod_warmup_MB now come from the first line that matches "(<N> MB), in <S> s": the
#     completion line, in either form (.5's, .6-prep's, and the one with the leaf pages skipped). na if none.
#   - monerod_warmup_end_s (new): seconds from monerod's launch to that completion line's log timestamp (its first 23
#     characters, parsed with date -d; one decimal). na without a completion line, or if date cannot parse it.
#   - monerod_warmup_stopped (new): 1 if the log has an "Index warm-up stopped" line, else 0; na without a log.
#   - both new fields follow monerod_warmup_MB in RESULT (na in the early-abort RESULT). The "monerod warm-up:" log
#     line prints the completion line. Nothing else changes.
#
# usage: hdd_run.sh <label> <monerod binary> [extra monerod args...]
# environment (all required unless a default is shown):
#   SNAP_MDB    path to the snapshot's data.mdb (top block 3,106,400)
#   DATA_DIR    monerod data dir ON THE HDD (created; its testnet/lmdb is replaced each run)
#   PEER        host:port of the peer's P2P port, as seen from the VM
#   OUT_BASE    where run directories go (default: $HOME/hddruns)
#   TARGET_TOP  stop when the top block reaches this height (default 3106800: 400 blocks)
#   TIMEOUT_S   give up after this many seconds of syncing (default 7200)
#   RPC_PORT    local RPC port (default 28091)
#   RPC_WAIT_S  how long to wait for monerod's RPC to answer after start (default 600)
#   WARM_DBS    space-separated LMDB sub-DB names to read before the run (default empty: no warm step)
#   MDB_DUMP    mdb_dump tool (default mdb_dump); FINCORE: fincore tool (default fincore)
#   WARM_TOOL   (v5) with WARM_DBS: read them with this tool (warmcheck) instead of mdb_dump (default empty)
#   RES_EVERY_S residency sample interval (default 60); WINDOW_BLOCKS: window size for WINDOW lines (default 200)
#   MEM_MAX     MemoryMax of the scope (default empty: no scope, as in v3); infinity: a scope with no cap
#   POST_CHECK  1 (default) or 0: after monerod exits during the sync, restart it offline to read the DB's top and hash
#   SYSTEMD_RUN, SYSTEMCTL (defaults systemd-run, systemctl), CG_ROOT (cgroup v2 mount, default /sys/fs/cgroup)
set -u
LABEL=${1:?usage: hdd_run.sh <label> <monerod> [args...]}; BIN=${2:?monerod binary}; shift 2
: "${SNAP_MDB:?}" "${DATA_DIR:?}" "${PEER:?}"
OUT_BASE=${OUT_BASE:-$HOME/hddruns}; TARGET_TOP=${TARGET_TOP:-3106800}; TIMEOUT_S=${TIMEOUT_S:-7200}
RPC_PORT=${RPC_PORT:-28091}; RPC_WAIT_S=${RPC_WAIT_S:-600}
WARM_DBS=${WARM_DBS:-}; MDB_DUMP=${MDB_DUMP:-mdb_dump}; FINCORE=${FINCORE:-fincore}; WARM_TOOL=${WARM_TOOL:-}
RES_EVERY_S=${RES_EVERY_S:-60}; WINDOW_BLOCKS=${WINDOW_BLOCKS:-200}
MEM_MAX=${MEM_MAX:-}; POST_CHECK=${POST_CHECK:-1}
SYSTEMD_RUN=${SYSTEMD_RUN:-systemd-run}; SYSTEMCTL=${SYSTEMCTL:-systemctl}; CG_ROOT=${CG_ROOT:-/sys/fs/cgroup}
START_TOP=3106400
RA_SET=0; ra_old=""; RA_FILE=${RA_FILE:-}; UNIT=""; HOLD=""; CG=""; CGP=""
cleanup() { # on any exit: put read-ahead back and stop the scope (and whatever is still in it)
  if [ "$RA_SET" = 1 ]; then sudo sh -c "echo $ra_old > $RA_FILE"; RA_SET=0; fi
  if [ -n "$UNIT" ]; then
    # a holder whose scope never came up may still be in sudo or systemd-run: end it first, as root (a signal from
    # this user can fail while sudo has real UID 0), so it cannot create the scope after the stop below
    if [ -z "$CGP" ] && [ -n "$HOLD" ] && jobs -rp | grep -qx "$HOLD"; then sudo -n kill -TERM "$HOLD" > /dev/null 2>&1; fi
    sudo "$SYSTEMCTL" stop "$UNIT.scope" > /dev/null 2>&1; UNIT=""
  fi
}
trap cleanup EXIT
abort() { local rc=$1; shift; echo "ABORT $*" | tee -a "${S:-/dev/null}"; exit "$rc"; }
mem_bytes() { # a MemoryMax value -> what memory.max should read (systemd's K/M/G/T are powers of 1024)
  case $1 in
    infinity) echo max ;;
    *K) echo $(( ${1%K} * 1024 )) ;;
    *M) echo $(( ${1%M} * 1024 * 1024 )) ;;
    *G) echo $(( ${1%G} * 1024 * 1024 * 1024 )) ;;
    *T) echo $(( ${1%T} * 1024 * 1024 * 1024 * 1024 )) ;;
    *) echo "$1" ;;
  esac
}
[ -f "$SNAP_MDB" ] || abort 2 "SNAP_MDB $SNAP_MDB is not a file"
[ -x "$BIN" ] || abort 2 "monerod binary $BIN is not executable"
if [ -n "$WARM_DBS" ] && [ -n "$WARM_TOOL" ]; then [ -x "$WARM_TOOL" ] || abort 2 "WARM_TOOL $WARM_TOOL is not executable"
elif [ -n "$WARM_DBS" ]; then command -v "$MDB_DUMP" > /dev/null || abort 2 "WARM_DBS is set but $MDB_DUMP is not available"; fi
if [ -n "$MEM_MAX" ]; then
  [[ $MEM_MAX =~ ^(infinity|[0-9]+[KMGT]?)$ ]] || abort 2 "MEM_MAX=$MEM_MAX: use infinity, or an integer with an optional K, M, G or T suffix"
  command -v "$SYSTEMD_RUN" > /dev/null || abort 2 "MEM_MAX is set but $SYSTEMD_RUN is not available"
  command -v "$SYSTEMCTL" > /dev/null || abort 2 "MEM_MAX is set but $SYSTEMCTL is not available"
  grep -qw memory "$CG_ROOT/cgroup.controllers" 2> /dev/null || abort 2 "MEM_MAX is set but $CG_ROOT/cgroup.controllers lists no memory controller (cgroup v2 needed)"
fi
mkdir -p "$DATA_DIR/testnet/lmdb" || abort 2 "cannot create $DATA_DIR/testnet/lmdb"
if [ "$(realpath "$(dirname "$SNAP_MDB")")" = "$(realpath "$DATA_DIR/testnet/lmdb")" ]; then
  abort 2 "refusing: DATA_DIR/testnet/lmdb is the snapshot's own directory, and the run would overwrite it"
fi
snap_sz=$(stat -c %s "$SNAP_MDB") || abort 2 "cannot stat $SNAP_MDB"
need_kb=$(( snap_sz / 1024 + 4 * 1024 * 1024 ))
have_kb=$(( $(df --output=avail -k "$DATA_DIR" | tail -1) + $( [ -f "$DATA_DIR/testnet/lmdb/data.mdb" ] && stat -c %s "$DATA_DIR/testnet/lmdb/data.mdb" || echo 0) / 1024 ))
[ "$have_kb" -ge "$need_kb" ] || abort 2 "refusing: $DATA_DIR has ${have_kb} kB for the restore, needs ${need_kb} kB (snapshot + 4 GB)"
(exec 3<>"/dev/tcp/127.0.0.1/$RPC_PORT") 2>/dev/null && abort 2 "something already listens on 127.0.0.1:$RPC_PORT (a monerod left running?)"
OUT=$OUT_BASE/$(date -u +%Y%m%dT%H%M%SZ)-$LABEL
mkdir -p "$OUT" || abort 2 "cannot create $OUT"
S=$OUT/summary.txt
log() { echo "$*" | tee -a "$S"; }
rpc() { local d=${2-}; [ -n "$d" ] || d='{}'; curl -s -m 10 "http://127.0.0.1:$RPC_PORT/$1" -d "$d"; }
hash_at() { rpc json_rpc "{\"jsonrpc\":\"2.0\",\"id\":0,\"method\":\"get_block_header_by_height\",\"params\":{\"height\":$1}}" \
  | grep -oE '"hash": "[0-9a-f]+"' | head -1 | cut -d'"' -f4; }
rpc_height() { local h; h=$(rpc get_height | grep -oE '"height": [0-9]+' | grep -oE '[0-9]+$'); echo "${h:-0}"; }
# the scope: join a process (by PID) to it, read its counters
cg_join() { sudo sh -c 'echo "$1" > "$2/cgroup.procs"' sh "$1" "$CGP" && grep -qx "$1" "$CGP/cgroup.procs"; }
cg_event() { awk -v k="$1" '$1 == k {print $2}' "$CGP/memory.events" 2> /dev/null; }
cg_stat() { awk -v k="$1" '$1 == k {print $2}' "$CGP/memory.stat" 2> /dev/null; }
cg_oom_killed() { [ -n "$CGP" ] && [ "$(cg_event oom_kill)" -gt 0 ] 2> /dev/null; }
cg_sample() { # t_s -> one cgmem.csv row
  awk -v t="$1" -v cur="$(cat "$CGP/memory.current" 2> /dev/null)" -v ev="$CGP/memory.events" '
    function v(a, k) {return (k in a) ? a[k] : 0}
    FILENAME == ev {e[$1] = $2; next}
    {s[$1] = $2}
    END {print t "," cur "," v(s, "anon") "," v(s, "file") "," v(s, "file_dirty") "," v(s, "file_writeback") "," v(s, "active_file") "," v(s, "inactive_file") "," v(s, "workingset_refault_file") "," v(e, "max") "," v(e, "oom_kill")}' \
    "$CGP/memory.stat" "$CGP/memory.events" 2> /dev/null
}
CGF_NA="cg_peak_MB=na cg_anon_max_MB=na cg_file_max_MB=na cg_oom=na cg_oom_kill=na cg_high=na cg_max=na cg_refault_file=na"
cg_end() { # read the scope's counters into CGF, then stop the scope
  if [ -z "$CGP" ]; then CGF="mem_max=none $CGF_NA"; return; fi
  if [ -d "$CGP" ]; then
    local pk amax fmax
    pk=$(cat "$CGP/memory.peak" 2> /dev/null); [[ $pk =~ ^[0-9]+$ ]] && pk=$((pk / 1000000)) || pk=na
    log "cgroup at the end: memory.peak $(cat "$CGP/memory.peak" 2> /dev/null || echo na); memory.events $(paste -sd' ' "$CGP/memory.events" 2> /dev/null); memory.stat $(awk '$1 ~ /^(anon|file|file_dirty|file_writeback|active_file|inactive_file|workingset_refault_file|workingset_activate_file|pgmajfault)$/ {printf "%s %s ", $1, $2}' "$CGP/memory.stat" 2> /dev/null)"
    read -r amax fmax <<< "$(awk -F, 'NR > 1 {if ($3 + 0 > a) a = $3 + 0; if ($4 + 0 > f) f = $4 + 0} END {printf "%d %d", a / 1e6, f / 1e6}' "$OUT/cgmem.csv" 2> /dev/null)"
    CGF="mem_max=$MEM_MAX cg_peak_MB=$pk cg_anon_max_MB=${amax:-na} cg_file_max_MB=${fmax:-na} cg_oom=$(cg_event oom) cg_oom_kill=$(cg_event oom_kill) cg_high=$(cg_event high) cg_max=$(cg_event max) cg_refault_file=$(cg_stat workingset_refault_file)"
  else
    log "cgroup at the end: $CGP is gone (the scope was stopped by something else)"
    CGF="mem_max=$MEM_MAX $CGF_NA"
  fi
  sudo "$SYSTEMCTL" stop "$UNIT.scope" > /dev/null 2>&1; UNIT=""
  wait "$HOLD" 2> /dev/null
  log "scope stopped"
}
stop_samplers() {
  kill ${IOS:-} ${VMS:-} ${PDS:-} 2> /dev/null
  if [ -n "${RES:-}" ]; then pkill -P "$RES" 2> /dev/null; kill "$RES" 2> /dev/null; RES=""; fi
}
early_result() { # an OOM-kill in the scope before the sync started: a result with no sync figures, exit 0
  if [ "$RA_SET" = 1 ]; then sudo sh -c "echo $ra_old > $RA_FILE"; RA_SET=0; log "warm: read-ahead restored to $ra_old kB"; fi
  stop_samplers; cg_end
  log "end $(date -u +%FT%TZ)"
  log "RESULT label=$LABEL top=$START_TOP blocks=0 wall_s=na warmup_s=na steady_blocks_per_s=na cpu_s=na cpu_per_wall=na disk_read_MB=na disk_write_MB=na warm_s=${warm_s:-0} warm_read_MB=${warm_read_MB:-0} resident_MB_start=${resident_MB_start:-na} resident_MB_end=na outcome=$1 $CGF rss_anon_max_MB=na post_check=na launch_to_rpc_s=na launch_to_top_s=na read_MB_launch=na monerod_warmup_s=na monerod_warmup_MB=na monerod_warmup_end_s=na monerod_warmup_stopped=na hash_at_$START_TOP=na"
  log "files: $(ls "$OUT" | paste -sd' ')"
  echo "HDD_RUN_DONE $OUT"; exit 0
}

log "kit v6; label $LABEL; binary $BIN ($(sha256sum "$BIN" | cut -c1-16)); extra args: $*"
if [ -n "$WARM_DBS" ] && [ -n "$WARM_TOOL" ]; then log "warm tool $WARM_TOOL ($(sha256sum "$WARM_TOOL" | cut -c1-16))"; fi
log "start $(date -u +%FT%TZ); target top $TARGET_TOP; timeout $TIMEOUT_S s; MEM_MAX ${MEM_MAX:-none}"
"$BIN" --version | tail -1 | tee -a "$S"
DEV=$(df --output=source "$DATA_DIR" | tail -1)
DISK=$(lsblk -no pkname "$DEV" 2>/dev/null | head -1); [ -n "$DISK" ] || DISK=$(lsblk -no kname "$DEV" 2>/dev/null | head -1); DISK=${DISK:-$(basename "$DEV")}
if [ -n "$WARM_DBS" ] && [ -z "$WARM_TOOL" ]; then
  if [ -z "$RA_FILE" ]; then
    kname=$(lsblk -no kname "$DEV" 2>/dev/null | head -1)
    RA_FILE=/sys/block/$kname/queue/read_ahead_kb; [ -n "$kname" ] && [ -e "$RA_FILE" ] || RA_FILE=/sys/block/$DISK/queue/read_ahead_kb
  fi
  [ -r "$RA_FILE" ] || abort 2 "WARM_DBS is set but read-ahead file $RA_FILE is not readable"
fi
log "data dir $DATA_DIR on $DEV (disk $DISK); snapshot $SNAP_MDB ($snap_sz bytes)"
lsblk -o NAME,ROTA,SCHED,RA,SIZE,MODEL 2>/dev/null | tee -a "$S"
log "nproc $(nproc); MemTotal $(awk '/^MemTotal/ {print $2" kB"}' /proc/meminfo); MemAvailable $(awk '/^MemAvailable/ {print $2" kB"}' /proc/meminfo); SwapTotal $(awk '/^SwapTotal/ {print $2" kB"}' /proc/meminfo); kernel $(uname -r)"
log "systemd-oomd $("$SYSTEMCTL" is-active systemd-oomd 2> /dev/null | head -1); lru_gen $(cat /sys/kernel/mm/lru_gen/enabled 2> /dev/null || echo na)"

# 1. restore the snapshot onto the HDD, check it, then drop caches. Any failure here aborts before monerod starts.
rm -f "${DATA_DIR:?}/testnet/lmdb/data.mdb" "${DATA_DIR:?}/testnet/lmdb/lock.mdb" || abort 3 "cannot remove the old DB files"
[ ! -e "$DATA_DIR/testnet/lmdb/data.mdb" ] || abort 3 "old data.mdb still present"
t0=$(date +%s.%N)
dd if="$SNAP_MDB" of="$DATA_DIR/testnet/lmdb/data.mdb" bs=16M oflag=direct status=none || abort 3 "restore: dd failed (exit $?)"
sync || abort 3 "restore: sync failed"
t1=$(date +%s.%N)
sz=$(stat -c %s "$DATA_DIR/testnet/lmdb/data.mdb" 2>/dev/null || echo 0)
[ "$sz" = "$snap_sz" ] || abort 3 "restore: copy is $sz bytes, snapshot is $snap_sz bytes"
log "restore: $sz bytes in $(awk -v a=$t0 -v b=$t1 'BEGIN {printf "%.1f", b - a}') s ($(awk -v a=$t0 -v b=$t1 -v s=$sz 'BEGIN {printf "%.0f", s / (b - a) / 1e6}') MB/s, sequential write); size matches the snapshot"
sudo sh -c 'sync; echo 3 > /proc/sys/vm/drop_caches' || abort 3 "could not drop the page cache"
log "page cache dropped"

# 1a. the scope (MEM_MAX set): held open by `sleep infinity`; checked; a test process is moved into it and back out
if [ -n "$MEM_MAX" ]; then
  UNIT=hddrun-$(date -u +%Y%m%dT%H%M%SZ)-$$
  # -n and stdin from /dev/null: a backgrounded sudo must never wait for a password or the terminal
  sudo -n "$SYSTEMD_RUN" --scope --quiet --unit="$UNIT" -p MemoryMax="$MEM_MAX" -p MemorySwapMax=0 -p OOMPolicy=continue \
    -- sleep infinity < /dev/null > "$OUT/scope.txt" 2>&1 &
  HOLD=$!
  # Is the holder still running? Ask bash's job table, not `kill -0`: sudo runs with real UID 0 during its policy
  # check, so a `kill -0` from this user fails with EPERM in that window (long after a cache drop on an HDD), which
  # v4 took for an exited holder. `jobs -rp` uses no signal and no /proc.
  held=1
  for i in $(seq 1 60); do
    CG=$("$SYSTEMCTL" show -p ControlGroup --value "$UNIT.scope" 2> /dev/null)
    [ -n "$CG" ] && [ -f "$CG_ROOT$CG/memory.max" ] && break
    CG=""; jobs -rp | grep -qx "$HOLD" || { held=0; break; }
    sleep 0.5
  done
  if [ -z "$CG" ]; then
    if [ "$held" = 0 ]; then why="systemd-run (under sudo) exited"; else why="not visible after 30 s"; fi
    abort 3 "scope: $UNIT.scope did not come up ($why): $(tail -3 "$OUT/scope.txt" | paste -sd' ')"
  fi
  CGP=$CG_ROOT$CG
  mm=$(cat "$CGP/memory.max"); want=$(mem_bytes "$MEM_MAX")
  [ "$mm" = "$want" ] || abort 3 "scope: memory.max reads $mm, expected $want for MemoryMax=$MEM_MAX"
  ( cg_join "$BASHPID" ) || abort 3 "scope: cannot move a process into $CGP"
  log "scope: $UNIT.scope, cgroup $CG, memory.max $mm, memory.swap.max $(cat "$CGP/memory.swap.max" 2> /dev/null || echo na), OOMPolicy $("$SYSTEMCTL" show -p OOMPolicy --value "$UNIT.scope" 2> /dev/null), memory.peak $([ -r "$CGP/memory.peak" ] && echo readable || echo MISSING)"
fi

# 1b. optional warm step: read the named sub-DBs through mdb_dump, inside the scope if there is one (no cache drop after this)
warm_s=0; warm_read_MB=0
if [ -n "$WARM_DBS" ] && [ -n "$WARM_TOOL" ]; then
  # v5: one call of the warm tool (mdb_env_warm_dbis) on all the named sub-DBs, read-ahead as it is
  statf=/sys/block/$DISK/stat; mbok=1
  [ -r "$statf" ] || { log "warm: $statf missing; MB read will be na"; mbok=0; }
  log "warm: $WARM_TOOL on $WARM_DBS; read-ahead left at $(cat "/sys/block/$DISK/queue/read_ahead_kb" 2> /dev/null || echo na) kB"
  s0=0; [ $mbok = 1 ] && s0=$(awk '{print $3}' "$statf")
  tw0=$(date +%s.%N)
  # shellcheck disable=SC2086
  ( if [ -n "$CGP" ]; then cg_join "$BASHPID" || exit 98; fi; exec "$WARM_TOOL" "$DATA_DIR/testnet/lmdb" all $WARM_DBS ) > "$OUT/warm_tool.txt" 2>&1; rc=$?
  tw1=$(date +%s.%N)
  if [ $rc != 0 ]; then
    [ $rc = 98 ] && abort 3 "warm: cannot move $WARM_TOOL into the scope"
    if cg_oom_killed; then log "warm: $WARM_TOOL was OOM-killed in the scope (exit $rc)"; early_result oom_killed_walk; fi
    tail -3 "$OUT/warm_tool.txt" | tee -a "$S"
    abort 3 "warm: $WARM_TOOL failed (exit $rc)"
  fi
  grep '^RESULT' "$OUT/warm_tool.txt" | sed 's/^RESULT/warm tool:/' | tee -a "$S"
  warm_s=$(awk -v a=$tw0 -v b=$tw1 'BEGIN {printf "%.1f", b - a}')
  if [ $mbok = 1 ]; then warm_read_MB=$(( ($(awk '{print $3}' "$statf") - s0) * 512 / 1000000 )); else warm_read_MB=na; fi
  log "warm: total $warm_s s, $warm_read_MB MB read"
  [ -n "$CGP" ] && log "warm: scope memory.current $(cat "$CGP/memory.current" 2> /dev/null), memory.peak $(cat "$CGP/memory.peak" 2> /dev/null || echo na)"
elif [ -n "$WARM_DBS" ]; then
  statf=/sys/block/$DISK/stat; mbok=1
  [ -r "$statf" ] || { log "warm: $statf missing; MB read will be na"; mbok=0; }
  ra_old=$(cat "$RA_FILE")
  RA_SET=1
  sudo sh -c "echo 0 > $RA_FILE" || abort 3 "warm: cannot set read-ahead to 0"
  [ "$(cat "$RA_FILE")" = 0 ] || abort 3 "warm: read-ahead not set to 0"
  log "warm: read-ahead 0 for the walk (was $ra_old kB, $RA_FILE)"
  tw0=$(date +%s.%N); sect=0
  for db in $WARM_DBS; do
    s0=0; [ $mbok = 1 ] && s0=$(awk '{print $3}' "$statf")
    ta=$(date +%s.%N)
    ( if [ -n "$CGP" ]; then cg_join "$BASHPID" || exit 98; fi; exec "$MDB_DUMP" -s "$db" "$DATA_DIR/testnet/lmdb" ) > /dev/null; rc=$?
    if [ $rc != 0 ]; then
      [ $rc = 98 ] && abort 3 "warm: cannot move mdb_dump into the scope"
      if cg_oom_killed; then log "warm: mdb_dump -s $db was OOM-killed in the scope (exit $rc)"; early_result oom_killed_walk; fi
      abort 3 "warm: mdb_dump -s $db failed"
    fi
    tb=$(date +%s.%N)
    if [ $mbok = 1 ]; then
      s1=$(awk '{print $3}' "$statf"); sect=$((sect + s1 - s0))
      mb=$(awk -v a=$s0 -v b=$s1 'BEGIN {printf "%.1f", (b - a) * 512 / 1e6}')
    else mb=na; fi
    log "warm: $db $(awk -v a=$ta -v b=$tb 'BEGIN {printf "%.1f", b - a}') s, $mb MB read"
  done
  tw1=$(date +%s.%N)
  sudo sh -c "echo $ra_old > $RA_FILE"
  [ "$(cat "$RA_FILE")" = "$ra_old" ] || abort 3 "warm: read-ahead not restored"
  RA_SET=0
  log "warm: read-ahead restored to $ra_old kB"
  warm_s=$(awk -v a=$tw0 -v b=$tw1 'BEGIN {printf "%.1f", b - a}')
  if [ $mbok = 1 ]; then warm_read_MB=$((sect * 512 / 1000000)); else warm_read_MB=na; fi
  log "warm: total $warm_s s, $warm_read_MB MB read"
  [ -n "$CGP" ] && log "warm: scope memory.current $(cat "$CGP/memory.current" 2> /dev/null), memory.peak $(cat "$CGP/memory.peak" 2> /dev/null || echo na)"
fi

# 1c. page-cache residency of data.mdb
MDB_FILE=$DATA_DIR/testnet/lmdb/data.mdb; RES=""
resident_MB() { local b; b=$("$FINCORE" --bytes --noheadings --output RES "$MDB_FILE" 2>/dev/null | awk '{s += $1} END {print s + 0}'); echo $((b / 1000000)); }
if command -v "$FINCORE" > /dev/null; then
  resident_MB_start=$(resident_MB)
  echo "epoch_s,resident_bytes" > "$OUT/residency.csv"
  ( while :; do echo "$(date +%s),$("$FINCORE" --bytes --noheadings --output RES "$MDB_FILE" 2>/dev/null | awk '{s += $1} END {print s + 0}')" >> "$OUT/residency.csv"; sleep "$RES_EVERY_S"; done ) & RES=$!
else
  log "fincore not available; no residency samples"; resident_MB_start=na
fi
resident_MB_end=na

# 2. samplers
ios_t0=$(date +%s)
iostat -x -y -t 1 > "$OUT/iostat.txt" 2>&1 & IOS=$!
vmstat -t -n 1 > "$OUT/vmstat.txt" 2>&1 & VMS=$!

# 3. monerod, inside the scope if there is one: the subshell joins the scope, then execs monerod (same PID)
launch=$(date +%s.%N)
( if [ -n "$CGP" ]; then cg_join "$BASHPID" || { echo "kit: cannot move monerod into the scope"; exit 98; }; fi
  exec "$BIN" --testnet --data-dir "$DATA_DIR" --add-exclusive-node "$PEER" --non-interactive --no-igd --no-zmq \
  --hide-my-port --out-peers 1 --in-peers 0 --p2p-bind-ip 127.0.0.1 --p2p-bind-port 28090 \
  --rpc-bind-ip 127.0.0.1 --rpc-bind-port "$RPC_PORT" \
  --log-file "$OUT/monerod.log" --log-level 0 "$@" ) > "$OUT/stdout.txt" 2>&1 &
MP=$!
pidstat -d -u -h -p $MP 1 > "$OUT/pidstat.txt" 2>&1 & PDS=$!
up=0
for i in $(seq 1 "$RPC_WAIT_S"); do
  rpc get_height | grep -q '"height"' && { up=1; break; }
  kill -0 $MP 2>/dev/null || break
  sleep 1
done
if [ $up -ne 1 ]; then
  if ! kill -0 $MP 2> /dev/null && cg_oom_killed; then
    log "monerod was OOM-killed in the scope before its RPC answered"; early_result oom_killed_startup
  fi
  kill -0 $MP 2>/dev/null && { kill -TERM $MP; sleep 30; kill -KILL $MP 2>/dev/null; }
  stop_samplers
  log "monerod did not answer RPC within $RPC_WAIT_S s (or exited); last stdout lines:"; tail -5 "$OUT/stdout.txt" | tee -a "$S"
  abort 4 "no RPC from monerod"
fi
start=$(date +%s); l2r=$(awk -v a="$launch" -v b="$(date +%s.%N)" 'BEGIN {printf "%.1f", b - a}')
log "monerod pid $MP answering RPC at $(date -u +%FT%TZ), $l2r s after launch; rpc_epoch=$start; cmdline $(tr '\0' ' ' < /proc/$MP/cmdline 2> /dev/null | cut -c1-200)"
[ -n "$CGP" ] && log "monerod in the scope: $(grep -qx "$MP" "$CGP/cgroup.procs" && echo yes || echo NO)"

# 4. poll
echo "t_s,height" > "$OUT/height.csv"
echo "t_s,rchar,wchar,syscr,syscw,read_bytes,write_bytes,utime_ticks,stime_ticks,rss_kb,rss_anon_kb,rss_file_kb" > "$OUT/proc.csv"
[ -n "$CGP" ] && echo "t_s,current,anon,file,file_dirty,file_writeback,active_file,inactive_file,workingset_refault_file,events_max,events_oom_kill" > "$OUT/cgmem.csv"
hz=$(getconf CLK_TCK); top=0; n=0
while kill -0 $MP 2>/dev/null; do
  now=$(date +%s); el=$((now - start))
  io=$(awk '{print $2}' /proc/$MP/io 2>/dev/null | head -6 | paste -sd,)
  st=$(awk '{print $14","$15}' /proc/$MP/stat 2>/dev/null)
  mem=$(awk '/^VmRSS/ {r = $2} /^RssAnon/ {a = $2} /^RssFile/ {f = $2} END {print r "," a "," f}' /proc/$MP/status 2>/dev/null)
  [ -n "$io" ] && [ -n "$st" ] && echo "$el,$io,$st,$mem" >> "$OUT/proc.csv"
  if [ $((n % 2)) -eq 0 ]; then
    # the scope's sample is taken with the proc sample, before the RPC call (which can take seconds under memory pressure)
    [ -n "$CGP" ] && cg_sample "$el" >> "$OUT/cgmem.csv"
    h=$(rpc_height)
    echo "$el,$h" >> "$OUT/height.csv"
    [ "$h" -gt 0 ] && top=$((h - 1))
    [ "$top" -ge "$TARGET_TOP" ] && break
  fi
  [ "$el" -ge "$TIMEOUT_S" ] && { log "TIMEOUT at top $top"; break; }
  n=$((n + 1)); sleep 1
done
end=$(date +%s); end_ns=$(date +%s.%N)

# 5. result, stop, summary
outcome=ok; post=na; hash=""
last=$(tail -1 "$OUT/proc.csv"); first=$(sed -n 2p "$OUT/proc.csv")
if kill -0 $MP 2> /dev/null; then
  cpu=$(awk -v hz=$hz '{printf "%.1f", ($14+$15)/hz}' /proc/$MP/stat 2>/dev/null)
  if [ "$top" -ge "$TARGET_TOP" ]; then H=$TARGET_TOP; else outcome=timeout; H=$top; fi
  hash=$(hash_at "$H")
  rpc stop_daemon > /dev/null
  for i in $(seq 1 180); do kill -0 $MP 2>/dev/null || break; sleep 1; done
  kill -0 $MP 2>/dev/null && { kill -TERM $MP; sleep 30; kill -KILL $MP 2>/dev/null; log "monerod had to be killed"; }
  wait $MP 2> /dev/null
  [ -n "$RES" ] && resident_MB_end=$(resident_MB)
  stop_samplers
else
  wait $MP; mrc=$?
  cpu=$(echo "$last" | awk -F, -v hz=$hz 'NR == 1 && $8 != "" {printf "%.1f", ($8 + $9) / hz}')
  if cg_oom_killed; then outcome=oom_killed; else outcome=exited; fi
  log "monerod exited during the sync: exit status $mrc, outcome $outcome, last polled top $top"
  [ -n "$RES" ] && resident_MB_end=$(resident_MB)
  stop_samplers
  H=$top
  if [ "$POST_CHECK" = 1 ]; then
    # restart monerod offline, outside the scope, to read the DB's top block and its hash
    "$BIN" --testnet --data-dir "$DATA_DIR" --offline --non-interactive --no-igd --no-zmq --out-peers 0 --in-peers 0 \
      --p2p-bind-ip 127.0.0.1 --p2p-bind-port 28090 --rpc-bind-ip 127.0.0.1 --rpc-bind-port "$RPC_PORT" \
      --log-file "$OUT/post_check.log" --log-level 0 > "$OUT/post_check.txt" 2>&1 &
    PP=$!; pup=0
    for i in $(seq 1 "$RPC_WAIT_S"); do
      rpc get_height | grep -q '"height"' && { pup=1; break; }
      kill -0 $PP 2> /dev/null || break
      sleep 1
    done
    if [ $pup = 1 ]; then
      ph=$(rpc_height); pc_top=$((ph - 1)); pc_hash=$(hash_at "$pc_top")
    fi
    rpc stop_daemon > /dev/null
    for i in $(seq 1 180); do kill -0 $PP 2> /dev/null || break; sleep 1; done
    kill -0 $PP 2> /dev/null && { kill -TERM $PP; sleep 30; kill -KILL $PP 2> /dev/null; }
    wait $PP 2> /dev/null
    if [ $pup = 1 ] && [ "${pc_top:-0}" -gt 0 ] && [ -n "${pc_hash:-}" ]; then
      post=ok; top=$pc_top; H=$pc_top; hash=$pc_hash
      log "post-check: monerod restarted offline, outside the scope: DB top $pc_top, hash $pc_hash"
    else
      post=failed; log "post-check: FAILED (no RPC, or no top or hash); see post_check.txt"
    fi
  fi
fi
cg_end
if [ -n "$first" ] && [ -n "$last" ]; then
  rb=$(( $(echo "$last" | cut -d, -f6) - $(echo "$first" | cut -d, -f6) ))
  wb=$(( $(echo "$last" | cut -d, -f7) - $(echo "$first" | cut -d, -f7) ))
  drm=$((rb / 1000000)); dwm=$((wb / 1000000))
else drm=na; dwm=na; fi
ranon=$(awk -F, 'NR > 1 && $11 + 0 > m {m = $11 + 0} END {printf "%d", m * 1024 / 1e6}' "$OUT/proc.csv")
wall=$((end - start))
# v5: from launch; monerod's own read bytes since launch; monerod .5's warm-up log line
if [ "$outcome" = ok ]; then l2t=$(awk -v a="$launch" -v b="$end_ns" 'BEGIN {printf "%.1f", b - a}'); else l2t=na; fi
if [ -n "$first" ] && [ -n "$last" ]; then rml=$(( $(echo "$last" | cut -d, -f6) / 1000000 )); else rml=na; fi
# v6: the completion line (the first with "(<N> MB), in <S> s"), its time from launch, and whether a stop line is there
wl=$(grep -m1 -E '\(([0-9]+) MB\), in ([0-9.]+) s' "$OUT/monerod.log" 2> /dev/null)
read -r mws mwmb <<< "$(sed -nE 's/.*\(([0-9]+) MB\), in ([0-9.]+) s.*/\2 \1/p' <<< "$wl")"
mws=${mws:-na}; mwmb=${mwmb:-na}; mwe=na
if [ -n "$wl" ] && wt=$(date -d "${wl:0:23}" +%s.%N 2> /dev/null); then mwe=$(awk -v a="$launch" -v b="$wt" 'BEGIN {printf "%.1f", b - a}'); fi
if [ -f "$OUT/monerod.log" ]; then if grep -q 'Index warm-up stopped' "$OUT/monerod.log"; then mwst=1; else mwst=0; fi; else mwst=na; fi
[ "$mws" = na ] || log "monerod warm-up: $(grep -o 'Index warm-up: .*' <<< "$wl")"
# warm-up: from RPC answering to the first sample with a height above the start; steady rate after that
read -r warm steady <<< "$(awk -F, -v h0=$((START_TOP + 1)) -v tend=$wall -v top=$top 'NR > 1 && $2 > h0 && !w {w = $1; hw = $2}
  END {if (w) printf "%d %.3f", w, (tend > w ? (top + 1 - hw) / (tend - w) : 0); else print "na na"}' "$OUT/height.csv")"
# iostat means for the data disk over the sync window (samples are 1 s; skip the ones before RPC answered)
ios=$(awk -v d="$DISK" -v skip=$((start - ios_t0)) -v n=$wall '
  $1 == "Device" {for (i = 1; i <= NF; i++) c[$i] = i; next}
  $1 == d {k++; if (k <= skip || k > skip + n) next; m++; rs += $c["r/s"]; ws += $c["w/s"]; ra += $c["r_await"]; wa += $c["w_await"]; u += $c["%util"]; rq += $c["rareq-sz"]; q += $c["aqu-sz"]}
  END {if (m) printf "iostat_samples=%d r_s=%.0f w_s=%.0f r_await_ms=%.1f w_await_ms=%.1f rareq_kB=%.1f aqu=%.2f util_pct=%.0f", m, rs/m, ws/m, ra/m, wa/m, rq/m, q/m, u/m; else print "iostat_samples=0"}' "$OUT/iostat.txt")
log "end $(date -u +%FT%TZ)"
log "RESULT label=$LABEL top=$top blocks=$((top - START_TOP)) wall_s=$wall warmup_s=$warm steady_blocks_per_s=$steady cpu_s=${cpu:-na} cpu_per_wall=$(awk -v c="${cpu:-}" -v w=$wall 'BEGIN {if (w > 0 && c != "") printf "%.2f", c / w; else printf "na"}') disk_read_MB=$drm disk_write_MB=$dwm warm_s=$warm_s warm_read_MB=$warm_read_MB resident_MB_start=$resident_MB_start resident_MB_end=$resident_MB_end outcome=$outcome $CGF rss_anon_max_MB=$ranon post_check=$post launch_to_rpc_s=$l2r launch_to_top_s=$l2t read_MB_launch=$rml monerod_warmup_s=$mws monerod_warmup_MB=$mwmb monerod_warmup_end_s=$mwe monerod_warmup_stopped=$mwst hash_at_$H=$hash"
log "IOSTAT label=$LABEL disk=$DISK $ios"
# windows of WINDOW_BLOCKS blocks: t(h) = first t_s with height-1 >= h; h_0 = START_TOP+1, h_k = START_TOP+k*W <= top
awk -F, -v s=$START_TOP -v W=$WINDOW_BLOCKS -v top=$top -v label="$LABEL" '
  FILENAME == ARGV[1] {if (FNR > 1) {ht[++nh] = $1; hh[nh] = $2}; next}
  FNR > 1 {pt[++np] = $1; pr[np] = $6; pw[np] = $7}
  function tof(h,   j) {for (j = 1; j <= nh; j++) if (hh[j] - 1 >= h) return ht[j]; return -1}
  function at(t, arr,   j, v) {v = arr[1]; for (j = 1; j <= np; j++) {if (pt[j] > t) break; v = arr[j]}; return v}
  END {
    h[0] = s + 1; for (k = 1; s + k * W <= top; k++) h[k] = s + k * W; K = k - 1
    for (k = 0; k <= K; k++) {t[k] = tof(h[k]); r[k] = at(t[k], pr); w[k] = at(t[k], pw)}
    for (k = 1; k <= K; k++) {
      if (t[k] < 0 || t[k-1] < 0) continue
      secs = t[k] - t[k-1]; bl = h[k] - h[k-1]
      bps = (secs > 0) ? sprintf("%.3f", bl / secs) : "na"
      printf "WINDOW label=%s k=%d from=%d to=%d secs=%d blocks_per_s=%s read_kB_per_block=%d write_kB_per_block=%d\n", label, k, h[k-1], h[k], secs, bps, (r[k] - r[k-1]) / 1000 / bl, (w[k] - w[k-1]) / 1000 / bl
    }
  }' "$OUT/height.csv" "$OUT/proc.csv" | while read -r wl; do log "$wl"; done
log "vmstat means over the run (us sy id wa): $(awk 'NR>2 && $1 ~ /^[0-9]+$/ {us+=$13; sy+=$14; id+=$15; wa+=$16; n++} END {if (n) printf "%.1f %.1f %.1f %.1f", us/n, sy/n, id/n, wa/n}' "$OUT/vmstat.txt")"
log "files: $(ls "$OUT" | paste -sd' ')"
echo "HDD_RUN_DONE $OUT"
